lessons.solution:
def summary(stock):
    stock.update({'pen': 50})
    low = []
    for name, qty in stock.items():
        if qty < 5:
            low.append(name)
    return {'names': sorted(stock.keys()), 'total': sum(stock.values()), 'ink': stock.get('ink', 0), 'low': sorted(low)}

def row_totals(table):
    totals = []
    for row in table:
        totals.append(sum(row))
    return totals

